package com.elogistic.backend.orders.internal.infrastructure;

import com.elogistic.backend.orders.api.*;
import com.elogistic.backend.orders.api.BusinessShipments.*;
import com.elogistic.backend.pricing.api.BusinessQuotes;
import java.security.MessageDigest;
import java.sql.*;
import java.time.*;
import java.time.temporal.ChronoUnit;
import java.util.*;
import javax.sql.DataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.json.JsonMapper;

public final class JdbcBusinessShipments implements BusinessShipments {
    private static final JsonMapper JSON=JsonMapper.builder().build();
    private final DataSource source;private final JdbcTemplate jdbc;private final BusinessPreparations drafts;private final BusinessPreparationProtection protection;private final Clock clock;private final boolean enabled;
    public JdbcBusinessShipments(DataSource source,BusinessPreparations drafts,BusinessPreparationProtection protection,Clock clock,boolean enabled){this.source=source;this.jdbc=new JdbcTemplate(source);this.drafts=drafts;this.protection=protection;this.clock=clock;this.enabled=enabled;}
    private static BusinessPreparations.Failure fail(String code){return new BusinessPreparations.Failure(code);}
    private UUID org(BusinessPreparations.Access a){a.requireCurrent();if(!enabled)throw fail("BUSINESS_DISABLED");if(!TransactionSynchronizationManager.isActualTransactionActive()||!TransactionSynchronizationManager.hasResource(source))throw new IllegalStateException("BUSINESS_SHIPPING_ADMISSION_REQUIRED");return a.scope().context().organizationId();}
    private void permit(BusinessPreparations.Access a,String p,UUID site){org(a);if(!a.scope().permits("shipment.draft.read",site)||!a.scope().permits(p,site))throw fail("RESOURCE_NOT_FOUND");}
    private Shipment row(ResultSet r,int ignored)throws SQLException{UUID id=r.getObject("id",UUID.class);var parcels=jdbc.query("SELECT id,parcel_number,description,quantity,weight_grams,length_mm,width_mm,height_mm,declared_value_vnd FROM orders.pilot_parcel WHERE shipment_id=? ORDER BY parcel_number",(p,n)->new PilotShipments.Parcel(p.getObject(1,UUID.class),p.getInt(2),new ShippingDrafts.Parcel(p.getString(3),p.getLong(4),p.getLong(5),p.getLong(6),p.getLong(7),p.getLong(8),p.getLong(9))),id);return new Shipment(id,r.getObject("organization_id",UUID.class),r.getObject("facility_id",UUID.class),r.getObject("creator_account_id",UUID.class),r.getString("code"),r.getObject("organization_preparation_id",UUID.class),r.getLong("organization_preparation_version"),r.getString("booking_state"),r.getString("carrier_state"),JSON.readValue(r.getString("draft_snapshot"),ShippingDrafts.Input.class),JSON.readValue(r.getString("quote_snapshot"),BusinessQuotes.Quote.class),r.getLong("total_vnd"),r.getTimestamp("created_at").toInstant(),parcels);}
    @Override public Shipment get(BusinessPreparations.Access a,UUID id){var rows=jdbc.query("SELECT * FROM orders.pilot_shipment WHERE owner_type='BUSINESS' AND organization_id=? AND id=?",this::row,org(a),id);if(rows.size()!=1)throw fail("RESOURCE_NOT_FOUND");Shipment s=rows.getFirst();permit(a,"shipment.draft.read",s.facilityId());a.requireCurrent();return s;}
    private record Stored(UUID target,UUID site,UUID preparation,long expected,UUID quote,String kid,byte[] hash){}
    private Optional<Stored> prior(BusinessPreparations.Access a,UUID key){return jdbc.query("SELECT target_id,facility_id,preparation_id,expected_version,quote_id,fingerprint_key_id,fingerprint FROM orders.organization_booking_receipt WHERE organization_id=? AND actor_account_id=? AND operation_key=?",(r,n)->new Stored(r.getObject(1,UUID.class),r.getObject(2,UUID.class),r.getObject(3,UUID.class),r.getLong(4),r.getObject(5,UUID.class),r.getString(6),r.getBytes(7)),org(a),a.actorAccountId(),key).stream().findFirst();}
    private byte[] hash(BusinessPreparations.Access a,String kid,UUID site,UUID draft,long version,UUID quote){return protection.hash(kid,"BUSINESS_BOOKING_V1",org(a),a.actorAccountId(),site,draft,version,quote);}
    @Override public Optional<Shipment> replay(BusinessPreparations.Access a,UUID draft,long version,UUID quote,UUID key){var old=prior(a,key);if(old.isEmpty())return Optional.empty();var r=old.get();permit(a,"shipment.book",r.site());byte[] h=hash(a,r.kid(),r.site(),draft,version,quote);try{if(!r.preparation().equals(draft)||r.expected()!=version||!r.quote().equals(quote)||!MessageDigest.isEqual(h,r.hash()))throw fail("IDEMPOTENCY_CONFLICT");}finally{Arrays.fill(h,(byte)0);Arrays.fill(r.hash(),(byte)0);}return Optional.of(get(a,r.target()));}
    @Override public BusinessPreparations.Draft requireBookable(BusinessPreparations.Access a,UUID id,long expected){var d=drafts.get(a,id);permit(a,"shipment.book",d.facilityId());permit(a,"shipment.quote",d.facilityId());a.scope().requireActiveFacility(d.facilityId());if(!d.state().equals("DRAFT")||d.version()!=expected)throw fail("PRECONDITION_STALE");return d;}
    private void one(int n){if(n!=1)throw new IllegalStateException("BUSINESS_BOOKING_ATOMIC_WRITE_REQUIRED");}
    @Override public Shipment confirm(BusinessPreparations.Access a,BusinessPreparations.Draft d,BusinessQuotes.Quote q,UUID key,UUID target){
        requireBookable(a,d.id(),d.version());if(!q.organizationId().equals(org(a))||!Objects.equals(q.facilityId(),d.facilityId())||!q.creatorAccountId().equals(a.actorAccountId())||!q.preparationId().equals(d.id())||q.preparationVersion()!=d.version()||!target.equals(q.consumedBy()))throw fail("PRECONDITION_STALE");
        Instant now=clock.instant().truncatedTo(ChronoUnit.MICROS);long next=d.version()+1;
        var after=new BusinessPreparations.Draft(d.id(),d.organizationId(),d.facilityId(),d.creatorAccountId(),"BOOKED",d.preparationState(),next,d.input(),d.sourceChannel(),d.sourceOrderReference(),d.createdAt(),now,List.of());
        one(jdbc.update("UPDATE orders.organization_preparation SET state='BOOKED',version=?,updated_at=? WHERE id=? AND organization_id=? AND version=? AND state='DRAFT'",next,Timestamp.from(now),d.id(),org(a),d.version()));
        one(jdbc.update("INSERT INTO orders.organization_preparation_version VALUES(?,?,?,?::jsonb,?)",d.id(),org(a),next,JSON.writeValueAsString(after),Timestamp.from(now)));
        one(jdbc.update("INSERT INTO orders.organization_preparation_audit(id,organization_id,actor_account_id,target_id,operation,prior_version,new_version,prior_state,new_state,request_id,occurred_at) VALUES(?,?,?,?,'BOOK',?,?,'DRAFT','BOOKED',?,?)",UUID.randomUUID(),org(a),a.actorAccountId(),d.id(),d.version(),next,a.requestId(),Timestamp.from(now)));
        one(jdbc.update("INSERT INTO orders.pilot_shipment(id,owner_type,organization_id,facility_id,creator_account_id,code,organization_preparation_id,organization_preparation_version,draft_version,booking_state,carrier_state,draft_snapshot,quote_snapshot,quote_id,total_vnd,created_at) VALUES (?,'BUSINESS',?,?,?,?,?,?,?,'CONFIRMED','NOT_ACCEPTED',?::jsonb,?::jsonb,?,?,?)",target,org(a),d.facilityId(),a.actorAccountId(),"AP-SIM-"+target.toString().replace("-",""),d.id(),d.version(),d.version(),JSON.writeValueAsString(d.input()),JSON.writeValueAsString(q),q.id(),q.totalVnd(),Timestamp.from(now)));
        for(int i=0;i<d.input().parcels().size();i++){var p=d.input().parcels().get(i);one(jdbc.update("INSERT INTO orders.pilot_parcel VALUES(?,?,?,?,?,?,?,?,?,?)",UUID.randomUUID(),target,i+1,p.description(),p.quantity(),p.weightGrams(),p.lengthMm(),p.widthMm(),p.heightMm(),p.declaredValueVnd()));}
        byte[] hash=hash(a,protection.active(),d.facilityId(),d.id(),d.version(),q.id());try{one(jdbc.update("INSERT INTO orders.organization_booking_receipt VALUES(?,?,?,?,?,?,?,?,?,?,?,?)",org(a),a.actorAccountId(),key,d.facilityId(),d.id(),d.version(),next,q.id(),target,protection.active(),hash,Timestamp.from(now)));}finally{Arrays.fill(hash,(byte)0);}
        a.meaningfulAction();return get(a,target);
    }
    @Override public UUID receipt(BusinessPreparations.Access a,UUID key){var r=prior(a,key).orElseThrow(()->fail("RESOURCE_NOT_FOUND"));permit(a,"shipment.book",r.site());return get(a,r.target()).id();}
    @Override public Page list(BusinessPreparations.Access a,int page,String search,String status){org(a);if(page<0||(search!=null&&(search.length()>160||search.codePoints().anyMatch(Character::isISOControl)))||(status!=null&&!status.isEmpty()&&!status.equals("WAITING_FOR_HANDOVER")))throw fail("VALIDATION_FAILED");
        String sql="SELECT * FROM orders.pilot_shipment WHERE owner_type='BUSINESS' AND organization_id=?";List<Object> args=new ArrayList<>();args.add(org(a));boolean all=a.scope().permits("shipment.draft.read",null);var sites=a.scope().facilities("shipment.draft.read");if(!all){if(sites.isEmpty())throw fail("RESOURCE_NOT_FOUND");sql+=" AND facility_id IN ("+String.join(",",Collections.nCopies(sites.size(),"?"))+")";args.addAll(sites);}
        if(search!=null&&!search.isBlank()){sql+=" AND lower(concat_ws(' ',code,draft_snapshot->>'reference',draft_snapshot#>>'{recipient,name}',draft_snapshot#>>'{recipient,phone}',CASE WHEN draft_snapshot#>>'{recipient,phone}' LIKE '+84%' THEN '0'||substring(draft_snapshot#>>'{recipient,phone}' FROM 4) END,(SELECT v.snapshot->>'sourceOrderReference' FROM orders.organization_preparation_version v WHERE v.id=organization_preparation_id AND v.organization_id=orders.pilot_shipment.organization_id AND v.version=organization_preparation_version))) LIKE ? ESCAPE '!'";args.add("%"+search.toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%");}sql+=" ORDER BY created_at DESC,id LIMIT 21 OFFSET ?";args.add(Math.multiplyExact((long)page,20));var rows=jdbc.query(sql,this::row,args.toArray());a.requireCurrent();return new Page(rows.stream().limit(20).toList(),page,20,rows.size()>20);
    }
    @Override public byte[] labels(BusinessPreparations.Access a,UUID id){var s=get(a,id);permit(a,"shipment.label.read",s.facilityId());byte[] result=new PilotLabelRenderer().render(s.code(),s.input(),s.quote().route(),s.parcels());a.requireCurrent();return result;}
}
